#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("uczniowie.txt");
    string imie;
    int wiek, ocena;
    int w17 = 0, dobrzy = 0;
    map<int, pair<int,int>> perWiek;
    while (plik >> imie >> wiek >> ocena) {
        if (wiek == 17) w17++;
        if (ocena >= 4 && wiek <= 18) dobrzy++;
        perWiek[wiek].first += ocena;
        perWiek[wiek].second++;
    }
    cout << "Uczniowie w wieku 17: " << w17 << endl;
    cout << "Uczniowie z ocena >= 4 i wiek <= 18: " << dobrzy << endl;
    cout << fixed << setprecision(2);
    cout << "Srednia ocen per wiek:" << endl;
    int bestWiek = 0;
    double bestAvg = -1;
    for (auto& p : perWiek) {
        double avg = (double)p.second.first / p.second.second;
        cout << "   " << p.first << ": " << avg << endl;
        if (avg > bestAvg) {
            bestAvg = avg;
            bestWiek = p.first;
        }
    }
    cout << "Wiek z najwyzsza srednia: " << bestWiek << " (" << bestAvg << ")" << endl;
    return 0;
}
```

